  insert into _new (slug, name, cat, kind, adult, sensitive, sourced, descr, longd) values
    ('demimasc', 'Demimasc', 'gender-identity', 'concept', false, false, true,
     'A gender identity in which a person is partially, but not wholly, masculine.',
     'Demimasc describes someone who identifies partly with masculinity and partly with something else — another gender, no gender, or a fluid mix. It sits in the same family as demiboy and demigirl, where the "demi-" prefix marks a partial rather than complete identification. Being demimasc says nothing about a person''s pronouns, presentation or assigned sex at birth.'),
    ('transbian', 'Transbian', 'sexual-orientation', 'concept', false, false, true,
     'A trans woman or transfeminine person who is a lesbian.',
     'Transbian is a self-descriptor combining "trans" and "lesbian", used by trans women and transfeminine people who are attracted to women. It is a term of community self-identification rather than a clinical category, and like most reclaimed vocabulary it is appropriate coming from people it describes.'),
    ('homocurious', 'Homocurious', 'questioning-labels', 'concept', false, false, true,
     'Someone who mainly identifies as straight but is curious about same-sex attraction or experience.',
     'Homocurious describes a person who generally considers themselves heterosexual while remaining open to, or actively exploring, attraction to the same gender. It parallels bi-curious and is usually a stage of self-description rather than a fixed identity; some people later adopt another label and some do not.'),
    ('pancurious', 'Pancurious', 'questioning-labels', 'concept', false, false, true,
     'Someone exploring whether pansexuality describes their attraction.',
     'Pancurious describes a person who is considering or exploring attraction that is not limited by gender, without yet claiming pansexual as an identity. As with other "-curious" terms it marks an open question rather than a settled answer.'),
    ('vegansexual', 'Vegansexual', 'sexual-orientation', 'concept', false, false, true,
     'A person who chooses sexual partners only among other vegans.',
     'Vegansexual describes someone whose choice of sexual partners is limited to other vegans, usually as an extension of an ethical commitment rather than a claim about attraction itself. The term was documented in New Zealand research in the mid-2000s and is a partner-selection preference rather than a sexual orientation in the usual sense.'),
    ('quoisexual', 'Quoisexual', 'sexual-orientation', 'concept', false, false, true,
     'A person for whom the distinction between sexual and other attraction does not apply or make sense.',
     'Quoisexual — from the French "quoi", meaning "what" — describes someone who cannot or does not separate sexual attraction from other kinds of attraction, or who finds the question itself unanswerable for them. It sits on the asexual spectrum and is the sexual counterpart of quoiromantic. It is a statement about the framework not fitting, rather than about the level of attraction.'),
    ('quoiromantic', 'Quoiromantic', 'sexual-orientation', 'concept', false, false, true,
     'A person for whom the distinction between romantic and platonic attraction does not apply or make sense.',
     'Quoiromantic, also called WTFromantic, describes someone who cannot distinguish romantic attraction from friendship or other closeness, or who finds that distinction meaningless for them. It sits on the aromantic spectrum. Like quoisexual, it describes a mismatch with the usual categories rather than an absence of feeling.'),
    ('aplatonic', 'Aplatonic', 'sexual-orientation', 'concept', false, false, true,
     'A person who experiences little or no platonic attraction — the pull toward friendship.',
     'Aplatonic people feel little or no desire to form friendships or close platonic bonds, in the same way an aromantic person feels little or no romantic attraction. It does not mean disliking people or being unable to maintain relationships; it describes the absence of a particular pull. The term comes from the aromantic and asexual communities, where attraction is routinely separated into distinct types.'),
    ('hijra', 'Hijra', 'gender-identity', 'concept', false, false, true,
     'A recognised third-gender community in South Asia, with centuries of documented history.',
     'Hijra refers to a third-gender community across India, Pakistan, Bangladesh and Nepal, generally comprising people assigned male at birth who live in a feminine gender role, alongside some intersex people. Hijra communities have their own kinship structures, and their presence is documented over centuries. India, Nepal, Pakistan and Bangladesh have each granted legal recognition to a third gender in recent decades. Hijra is a specific cultural identity, not a synonym for transgender, and should not be used as a general translation.'),
    ('polycule', 'Polycule', 'relationship-structures', 'concept', false, false, true,
     'The connected network of people linked by romantic or sexual relationships in a polyamorous group.',
     'A polycule is the whole web of people joined directly or indirectly by relationships — partners, partners'' partners, and so on. The word blends "poly" with "molecule", after the way such networks are drawn as diagrams. Polycules vary enormously: some function as a close unit, others are simply a map of who is connected to whom.'),
    ('consensual-non-monogamy', 'Consensual Non-Monogamy', 'relationship-structures', 'concept', false, false, true,
     'Any relationship structure where partners agree that more than one romantic or sexual relationship is permitted.',
     'Consensual non-monogamy, often shortened to CNM or ENM (ethical non-monogamy), is the umbrella for polyamory, open relationships, swinging, relationship anarchy and similar arrangements. The defining feature is informed agreement between everyone involved, which is what separates it from cheating. It describes a structure, not a level of commitment.'),
    ('new-relationship-energy-nre', 'New Relationship Energy (NRE)', 'relationship-structures', 'concept', false, false, true,
     'The intense excitement and preoccupation common in the early stage of a new relationship.',
     'New Relationship Energy describes the heightened attention, euphoria and urgency people often feel at the start of a relationship. The term is used widely in polyamorous communities because NRE with a new partner can unbalance existing relationships if it is not named and managed. It is generally understood as a temporary phase rather than a measure of how much a relationship matters.'),
    ('nesting-metamours', 'Nesting Metamours', 'relationship-structures', 'concept', false, false, true,
     'Metamours who share a home — partners of the same person who also live together.',
     'A metamour is your partner''s partner. Nesting metamours are metamours who also share a household, whether or not they are romantically involved with each other. The arrangement raises practical questions about space, finances and privacy that metamours living apart do not face.'),
    ('squish', 'Squish', 'relationship-structures', 'concept', false, false, true,
     'An intense desire for friendship with someone — the platonic counterpart of a crush.',
     'A squish is a strong pull toward friendship or close platonic connection with a particular person, without romantic or sexual desire. The term comes from the aromantic community, where separating types of attraction is standard, and gives a name to a feeling that English otherwise leaves to the vocabulary of romance.'),
    ('frottage', 'Frottage', 'practices-play', 'concept', true, true, true,
     'Sexual rubbing of the body against a partner, usually while clothed or without penetration.',
     'Frottage covers sexual activity in which people rub their bodies together for stimulation rather than engaging in penetration. Between men it is sometimes called frot. It carries a much lower risk of transmitting sexually transmitted infections than penetrative sex, which is one reason it appears in safer-sex guidance. The related term frotteurism describes non-consensual rubbing against another person and is a criminal act, not a practice.'),
    ('dry-humping', 'Dry Humping', 'practices-play', 'concept', true, true, true,
     'Rubbing the genitals against a partner or object while clothed.',
     'Dry humping is sexual rubbing that keeps clothing on. It is a common form of contact for people avoiding penetration, and carries a low risk of transmitting sexually transmitted infections while clothing remains a barrier.'),
    ('69-position', '69 Position', 'sex-positions', 'concept', true, true, true,
     'A position in which two people perform oral sex on each other at the same time.',
     'Named for the shape the numerals suggest, the 69 position has each partner oriented head-to-foot so both can give and receive oral sex simultaneously. It works with any combination of bodies, and comfort usually depends more on height difference and support than on anatomy.'),
    ('ear-licking', 'Ear Licking', 'practices-play', 'concept', true, true, true,
     'Oral stimulation of a partner''s ear.',
     'The outer ear and the skin around it are densely supplied with nerve endings, which is why licking, breathing on or lightly biting the ear is a common part of foreplay. Some people find it intensely pleasurable and others find it uncomfortable, so it is worth asking.'),
    ('hotdogging', 'Hotdogging', 'practices-play', 'concept', true, true, true,
     'Rubbing the penis between a partner''s buttocks without penetration.',
     'Hotdogging refers to sliding the penis between the buttocks or thighs rather than penetrating. Like other forms of frottage it carries substantially lower infection risk than penetrative sex.'),
    ('jilling-off', 'Jilling Off', 'practices-play', 'concept', true, true, true,
     'Female masturbation — the counterpart to "jacking off".',
     'Jilling off is informal slang for masturbation by women and people with vulvas, coined as a counterpart to the male-coded "jacking off". The term is playful rather than clinical.'),
    ('blumpkin', 'Blumpkin', 'practices-play', 'concept', true, true, true,
     'Receiving oral sex while sitting on a toilet and defecating.',
     'A blumpkin is a slang term for receiving fellatio while seated on a toilet using it. The term appears far more often in comedy and internet slang than as a described practice.'),
    ('rusty-trombone', 'Rusty Trombone', 'practices-play', 'concept', true, true, true,
     'Simultaneous anilingus and manual stimulation of the penis, performed from behind.',
     'The rusty trombone is a slang term for a combined act in which one partner performs anilingus while reaching around to stimulate the other''s penis by hand, the arm motion suggesting a trombone slide. As with any oral-anal contact, barriers substantially reduce the risk of transmitting gastrointestinal infections and hepatitis A.'),
    ('abasiophilia', 'Abasiophilia', 'fetishes-interests', 'concept', true, true, true,
     'Sexual attraction to people with impaired mobility, especially those using braces, casts or wheelchairs.',
     'Abasiophilia is attraction to people with limited mobility or to mobility aids such as leg braces, casts and wheelchairs. As with any attraction directed at a body or a device, the distinction that matters in practice is whether disabled people are treated as partners with their own agency or as objects of the interest.'),
    ('agoraphilia', 'Agoraphilia', 'fetishes-interests', 'concept', true, true, true,
     'Sexual arousal from sex in public or open spaces.',
     'Agoraphilia is arousal connected to having sex outdoors or in public places. The consent of everyone present is the governing issue: public sex where uninvolved people can see is illegal in most jurisdictions and is a consent violation regardless of the law, which is why the interest is usually practised at private outdoor locations or dedicated events.'),
    ('amychophilia', 'Amychophilia', 'fetishes-interests', 'concept', true, true, true,
     'Sexual arousal from being scratched, or from scratching a partner.',
     'Amychophilia is arousal from scratching — giving, receiving or the marks left behind. It overlaps with edge play and sensation play. Broken skin carries infection risk in both directions, so nails, hygiene and aftercare matter.'),
    ('emetophilia', 'Emetophilia', 'fetishes-interests', 'concept', true, true, true,
     'Sexual arousal from vomiting or from watching others vomit.',
     'Emetophilia, sometimes called Roman showers, is arousal connected to vomiting. It carries genuine physical risk: repeated induced vomiting damages tooth enamel and the oesophagus and can cause electrolyte disturbance, and vomit is an infection vector. It is also easily confused with, and can mask, an eating disorder.'),
    ('scopophilia', 'Scopophilia', 'fetishes-interests', 'concept', true, true, true,
     'Sexual pleasure derived from looking — the arousal of watching.',
     'Scopophilia is pleasure taken in looking, and appears both in psychoanalytic writing and in film theory, where Laura Mulvey used it in her account of the gaze. In a kink context it overlaps with voyeurism, with the same governing condition: the person being watched has agreed to it.'),
    ('martymachlia', 'Martymachlia', 'fetishes-interests', 'concept', true, true, true,
     'Sexual arousal from being watched by others during sex.',
     'Martymachlia is arousal from having an audience — the complement of voyeurism. It is a common reason people attend play parties and dedicated venues, where being watched is an agreed part of the setting rather than something imposed on bystanders.'),
    ('narratophilia', 'Narratophilia', 'fetishes-interests', 'concept', true, true, true,
     'Sexual arousal from hearing or telling erotic words and stories.',
     'Narratophilia is arousal driven by language — dirty talk, read or spoken erotica, or narrated fantasy. It is one of the interests that translates most easily to distance and text, and it underpins much of audio erotica.'),
    ('melolagnia', 'Melolagnia', 'fetishes-interests', 'concept', true, true, true,
     'Sexual arousal from music.',
     'Melolagnia is arousal produced by music itself, rather than by lyrics or associated imagery. It shades into the widely reported experience of music producing strong physical responses, sometimes called frisson.'),
    ('dormaphilia', 'Dormaphilia', 'fetishes-interests', 'concept', true, true, true,
     'Sexual arousal connected to a sleeping partner.',
     'Dormaphilia is arousal connected to sleep — a partner asleep, or the appearance of sleep. Consent is the whole of the matter here: a sleeping person cannot consent in the moment, so any practice in this area depends entirely on explicit agreement negotiated in advance while both people are awake, and on a clear means of withdrawing it.'),
    ('onychophilia', 'Onychophilia', 'fetishes-interests', 'concept', true, true, true,
